    } else if (args.args && typeof args.args === "object" && !Array.isArray(args.args) && Object.keys(args).length === 1) {
      args = args.args;
    }
    return { args: JSON.stringify(args), repaired: outerRepaired };
  }
  return { args: JSON.stringify(args || {}), repaired: "none" };
}

